begin;
-- V11 is optional; all published recordings remain free.
drop policy if exists "published entitled content" on public.evolve_member_content;
drop policy if exists "published member content" on public.evolve_member_content;
create function public.evolve_verified() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) $$;
revoke all on function public.evolve_verified() from public,anon,authenticated;
grant execute on function public.evolve_verified() to authenticated;
create policy "published member content" on public.evolve_member_content for select to authenticated using (published and public.evolve_verified());
create table public.evolve_contacts(user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null check(char_length(full_name)<=100),phone text not null default '' check(char_length(phone)<=40),email_marketing boolean not null default false,whatsapp_marketing boolean not null default false,updated_at timestamptz not null default now(),check(not whatsapp_marketing or phone<>''));
create table public.evolve_consent_history(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,email_marketing boolean not null,whatsapp_marketing boolean not null,recorded_at timestamptz not null default now(),notice_version text not null default '2026-11-v1');
create function public.evolve_record_consent() returns trigger language plpgsql security definer set search_path='' as $$ begin new.updated_at=now(); insert into public.evolve_consent_history(user_id,email_marketing,whatsapp_marketing) values(new.user_id,new.email_marketing,new.whatsapp_marketing); return new; end $$;
create trigger evolve_consent_log before insert or update on public.evolve_contacts for each row execute function public.evolve_record_consent();
create table public.evolve_private_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,service text not null check(service in ('Personal training','Nutrition guidance','Workout consultation','Wellness coaching','Accountability','Transformation consultation')),requested_at timestamptz not null,created_at timestamptz not null default now(),status text not null default 'requested' check(status in ('requested','confirmed','declined','cancelled','completed')),payment_status text not null default 'unpaid' check(payment_status in ('unpaid','paid','refunded')),price_cents integer not null default 25000 check(price_cents=25000));
alter table public.evolve_bookings add column if not exists price_cents integer not null default 15000 check(price_cents=15000),add column if not exists payment_status text not null default 'unpaid' check(payment_status in ('unpaid','paid','refunded'));
alter table public.evolve_contacts enable row level security;
alter table public.evolve_consent_history enable row level security;
alter table public.evolve_private_sessions enable row level security;
revoke all on public.evolve_contacts,public.evolve_consent_history,public.evolve_private_sessions from public,anon,authenticated;
grant select,insert,update on public.evolve_contacts to authenticated;
grant select on public.evolve_consent_history,public.evolve_private_sessions to authenticated;
grant insert(user_id,service,requested_at) on public.evolve_private_sessions to authenticated;
grant update(status,payment_status) on public.evolve_private_sessions to authenticated;
grant update(payment_status) on public.evolve_bookings to authenticated;
create policy "contact owner read" on public.evolve_contacts for select to authenticated using(user_id=auth.uid() or public.evolve_is_admin());
create policy "contact owner insert" on public.evolve_contacts for insert to authenticated with check(user_id=auth.uid() and public.evolve_verified());
create policy "contact owner update" on public.evolve_contacts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and public.evolve_verified());
create policy "consent read" on public.evolve_consent_history for select to authenticated using(user_id=auth.uid() or public.evolve_is_admin());
create policy "private session read" on public.evolve_private_sessions for select to authenticated using(user_id=auth.uid() or public.evolve_is_admin());
create policy "private session request" on public.evolve_private_sessions for insert to authenticated with check(user_id=auth.uid() and public.evolve_verified() and requested_at>now());
create policy "private session admin update" on public.evolve_private_sessions for update to authenticated using(public.evolve_is_admin()) with check(public.evolve_is_admin());
create policy "booking admin payment update" on public.evolve_bookings for update to authenticated using(public.evolve_is_admin()) with check(public.evolve_is_admin());
commit;